const historiaZamowien = ["Z-001", "Z-002", "Z-003"];

function pokazOdNajnowszych(zamowienia) {
  return [...zamowienia].reverse(); // POPRAWNIE: dzialamy na KOPII
}

console.log(pokazOdNajnowszych(historiaZamowien)); // ['Z-003', 'Z-002', 'Z-001']
console.log(historiaZamowien); // ['Z-001', 'Z-002', 'Z-003'] - oryginal NIENARUSZONY

