const liczby = [1, 2, 3, 4, 5];
const usuniety = liczby.pop();
console.log(usuniety); // 5
console.log(liczby);   // [1, 2, 3, 4]

const temperatury = [15, 22, 8];
const kopia = [...temperatury];
kopia.reverse();

console.log(kopia);        // [8, 22, 15]
console.log(temperatury);  // [15, 22, 8] - NIEZMIENIONY

const liczby = [1, 2, 3, 4, 5, 6, 7];
const fragment = liczby.slice(1, 4);
console.log(fragment); // [2, 3, 4]
console.log(liczby);   // [1, 2, 3, 4, 5, 6, 7] - NIEZMIENIONY

function pokazOdNajnowszychZle(zamowienia) {
  return zamowienia.reverse();
}

const historia = ["Z-1", "Z-2", "Z-3"];
pokazOdNajnowszychZle(historia);
console.log(historia); // ['Z-3', 'Z-2', 'Z-1'] - ZMUTOWANY oryginal!

function pokazOdNajnowszych(zamowienia) {
  return [...zamowienia].reverse();
}

const historia = ["Z-1", "Z-2", "Z-3"];
console.log(pokazOdNajnowszych(historia)); // ['Z-3', 'Z-2', 'Z-1']
console.log(historia); // ['Z-1', 'Z-2', 'Z-3'] - NIENARUSZONY

const tablica = [];
tablica.push("start");
console.log(tablica); // ['start']

tablica.push("srodek");
console.log(tablica); // ['start', 'srodek']

tablica.unshift("poczatek");
console.log(tablica); // ['poczatek', 'start', 'srodek']

tablica.pop();
console.log(tablica); // ['poczatek', 'start']
